  ///  tokens unsubstituted, so a formula written this way arrives with the
  ///  tokens still in place.
  IdBasedFormula? get idBased => wireGet('id_based') as IdBasedFormula?;
  set idBased(IdBasedFormula? value) => wireSet('id_based', value);

  @override
  FormulaCase wireCase(String name, Object payload) => switch (name) {
    'display_string' => FormulaDisplayStringCase(payload as String),
    'id_based' => FormulaIdBasedCase(payload as IdBasedFormula),
    _ => throw ArgumentError.value(name, 'name', 'no case of Formula'),
  };

  @override
  List<FormulaCase> unionCases() => super.unionCases().cast();

  @override
  FormulaCase? unionPrimary() => super.unionPrimary() as FormulaCase?;

