/// How a connection line is routed between its ends.
///
/// A curved route whose control position lies almost on the line between the
/// two ends is written back as `straight`, and that position is discarded.
class LineType extends TaggedUnionModel {
  /// Creates a [LineType] from its cases.
  new({
    Position? corner,
    Position? curved,
    bool? straight,
    super.presetIdentifier,
  }) : super.construct(schema, {
         'corner': corner,
         'curved': curved,
         if (straight ?? false) 'straight': true,
       });

  new _() : super.blank(schema);

  /// Creates a [LineType] from its cases, with [primary] designated
  /// as the case a reader acts on. A non-null [presetIdentifier] adopts
  /// that preset, as it does in the unnamed constructor.
  ///
  /// Throws [ArgumentError] if [primary] names no case of the class.
  factory unionOf(
    String primary, {
    Position? corner,
    Position? curved,
    bool? straight,
    String? presetIdentifier,
  }) => TaggedUnionModel.designate(
    schema,
    primary,
    () => LineType(
      corner: corner,
      curved: curved,
      straight: straight,
      presetIdentifier: presetIdentifier,
    ),
  );

  /// Decodes a [LineType] from its JSON, resolving presets through
  /// [context].
  ///
  /// Throws [ModelValidationError] if the JSON doesn't match the model,
  /// and [DocumentVersionError] if it declares a newer major version.
  factory fromJson(Object? json, [WireContext? context]) =>
      schema.fromJson(json, context);

  /// The metadata that the codec reads.
  static final UnionSchema<LineType> schema = UnionSchema(
    name: 'LineType',
    typeId: 'com.apple.apps.content-language.connection-line.line-type',
    version: const Version(1),
    create: LineType._,
    cases: [
      CaseSpec(
        'corner',
        const Version(1),
        type: ModelType(() => Position.schema),
      ),
      CaseSpec(
        'curved',
        const Version(1),
        type: ModelType(() => Position.schema),
      ),
      CaseSpec('straight', const Version(1)),
    ],
  );

  /// A route that makes right-angle turns and passes through this position,
  /// though not necessarily with a corner there.
  ///
  /// The reader usually passes straight through a position partway between the
  /// ends.
  Position? get corner => wireGet('corner') as Position?;
  set corner(Position? value) => wireSet('corner', value);

  /// A route that bows between the ends and passes through this position.
  Position? get curved => wireGet('curved') as Position?;
  set curved(Position? value) => wireSet('curved', value);

  /// A route that makes a straight line between its ends.
  bool get straight => wireGet('straight') != null;
  set straight(bool value) => wireSet('straight', value ? true : null);

  @override
