  /// Fixed denominator of 8.
  eighths('eighths'),

  /// Fixed denominator of 2 (for example, 0/2, 1/2).
  halves('halves'),

  /// Fixed denominator of 100.
  hundredths('hundredths'),

  /// Fixed denominator of 4 (for example, 1/4, 3/4).
  quarters('quarters'),

  /// Fixed denominator of 16.
  sixteenths('sixteenths'),

  /// Fixed denominator of 10.
  tenths('tenths'),

  /// At most one digit in the numerator and denominator (for example, 1/2,
  /// 3/4).
  upToOneDigit('up_to_one_digit'),

  /// At most three digits in the numerator and denominator.
  upToThreeDigits('up_to_three_digits'),

  /// At most two digits in the numerator and denominator (for example, 5/16,
  /// 22/87).
  upToTwoDigits('up_to_two_digits'),
}

